/*
 * THE COACH'S PEOPLE, AS THE SERVER WOULD HAND THEM OVER (TASK-L164 §2).
 *
 * Stands in for `getRoster()` (src/lib/server/coach/roster-service.ts): ONE
 * statement that starts from `accounts` and LEFT JOINs everything else, so a
 * learner who signed up and never finished onboarding still has a row. That is
 * L89's whole reason for existing — the old list started from
 * `project_contexts` and hid exactly the people a coach most needs to notice.
 *
 * EVERY DERIVED FIELD IS NULLABLE ON PURPOSE: email, coachLabel, projectName,
 * contextVersion (null = never finished onboarding), lastActivity (null, never
 * the word "never"), coachEmail, replanBlockedAt, awaitingReplySince (a DATE,
 * never a count). `cohorts` and `programmes` are `[]`, never null.
 *
 * STAFF-ONLY. `coachLabel` is the trainer's private shorthand (L84) and must
 * never reach a learner surface.
 *
 * The ORDER is the server's and is applied here, where the server's ORDER BY
 * would be: lastActivity descending, NULLS LAST, then createdAt descending. The
 * fixture's rows are deliberately NOT written in that order, so the sort is
 * exercised rather than assumed. The filter downstream decides nothing about
 * order.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}

const rows = plain(Inputs.items) || [];
const ms = (iso) => (iso ? new Date(iso).getTime() : null);

Outputs.people = rows.slice().sort((a, b) => {
  const la = ms(a.lastActivity);
  const lb = ms(b.lastActivity);
  if (la === null && lb !== null) return 1;
  if (lb === null && la !== null) return -1;
  if (la !== lb) return lb - la;
  return ms(b.createdAt) - ms(a.createdAt);
});
Outputs.count = rows.length;
Outputs.loaded();

